mapper.select:
SELECT c.id, c.no, c.warehouse_id, w.name AS warehouse_name, c.purpose, c.scope, c.count_date, c.counter_id, c.status, c.version, c.create_by, c.create_time, agg.item_count, agg.filled_count, agg.gain_count, agg.loss_count, cat.category_names FROM inv_count c JOIN bas_warehouse w ON w.id = c.warehouse_id LEFT JOIN LATERAL (SELECT COUNT(*) AS item_count, COUNT(i.counted_qty) AS filled_count, COUNT(*) FILTER (WHERE i.counted_qty > i.book_qty) AS gain_count, COUNT(*) FILTER (WHERE i.counted_qty < i.book_qty) AS loss_count FROM inv_count_item i WHERE i.count_id = c.id) agg ON true LEFT JOIN LATERAL (SELECT string_agg(COALESCE(pc.name || '-', '') || mc.name, '、' ORDER BY mc.code) AS category_names FROM inv_count_category cc JOIN bas_material_category mc ON mc.id = cc.category_id LEFT JOIN bas_material_category pc ON pc.id = mc.parent_id WHERE cc.count_id = c.id) cat ON true WHERE true AND (c.create_by = #{scope.userId} OR c.counter_id = #{scope.userId})
AND c.status IN #{s}
AND c.warehouse_id = #{q.warehouseId} AND c.purpose = #{q.purpose} AND c.count_date >= #{q.countDateFrom} AND c.count_date <= #{q.countDateTo}
AND c.id IN #{id}
AND (c.no ILIKE '%' || #{q.keyword} || '%' OR w.name ILIKE '%' || #{q.keyword} || '%' OR c.counter_id IN (SELECT u.id FROM sys_user u WHERE u.nickname ILIKE '%' || #{q.keyword} || '%') OR EXISTS (SELECT 1 FROM inv_count_item i JOIN bas_material_sku k ON k.id = i.material_sku_id JOIN bas_material m ON m.id = k.material_id WHERE i.count_id = c.id AND (k.code ILIKE '%' || #{q.keyword} || '%' OR m.code ILIKE '%' || #{q.keyword} || '%' OR m.name ILIKE '%' || #{q.keyword} || '%')) OR upper(c.no) IN #{code})
ORDER BY c.id DESC
